#include <iostream>
#include <string>

class BankAccount {
private:
    std::string accountNumber;
    double balance;

public:
    BankAccount(std::string id, double initialBalance)
        : accountNumber(std::move(id)), balance(initialBalance > 0.0 ? initialBalance : 0.0) {}

    void deposit(double amount) {
        if (amount > 0.0) {
            balance += amount;
        }
    }

    bool withdraw(double amount) {
        if (amount > 0.0 && amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    double getBalance() const {
        return balance;
    }
};

int main() {
    BankAccount acc("ACC12345", 500.0);
    acc.deposit(150.0);
    acc.withdraw(200.0);
    std::cout << "Current balance: $" << acc.getBalance() << "\n";
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    // std::vector offers direct value equality, copy assignment, and size awareness
    std::vector<int> v1 = {10, 20, 30};
    std::vector<int> v2 = v1; // Clean value copy (impossible with raw C-style arrays)

    std::cout << "v1 size: " << v1.size() << "\n";
    std::cout << "v1 and v2 equal? " << (v1 == v2 ? "yes" : "no") << "\n";

    v2[1] = 99;
    std::cout << "After modification, equal? " << (v1 == v2 ? "yes" : "no") << "\n";
    std::cout << "v2[1] is: " << v2[1] << "\n";
    return 0;
}
